mapper.update:
update sys_role
role_code = #{roleCode}, role_name = #{roleName}, data_scope = #{dataScope}, sort = #{sort}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = now()
where id = #{id}

mapper.select:
select count(*)
from sys_role
where del_flag = 0
  and role_code = #{roleCode}

    and id != #{excludeId}

select count(*)
from sys_role
where del_flag = 0
  and role_name = #{roleName}

    and id != #{excludeId}

select count(*)
from sys_employee_role
where role_id = #{roleId}

select permission_id
from sys_role_permission
where role_id = #{roleId}
